package local.snapexplorer.mobile;
import org.json.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;
public final class FullExportTest {
 static int checks;static void check(boolean b,String message){if(!b)throw new AssertionError(message);checks++;}
 public static void main(String[] args)throws Exception{
  String id="11111111-2222-3333-4444-555555555555";
  JSONObject record=new JSONObject("{\"Custom Sticker\":{\"ID\":\""+id+"\",\"Path\":\"custom_stickers/item.webp\"},\"Reply To\":{\"Media ID\":\"ignore-quoted\"},\"Creator\":{\"ID\":\"ignore-owner\"}}");
  List<String> refs=MediaReferences.collect(record,true);check(refs.contains(id)&&refs.contains("custom_stickers/item.webp"),"nested custom sticker references");check(!refs.contains("ignore-quoted")&&!refs.contains("ignore-owner"),"quote and profile metadata are not attachments");
  check(MediaReferences.localKeys("https://example.invalid/media/"+id+".png?signature=99999999999999999999999999999999&id=wrong-owner-id").equals(Arrays.asList(id)),"URL contributes only its explicit path identifier");
  check(MediaReferences.localKeys("https://example.invalid/download?media_id="+id).equals(Arrays.asList(id)),"explicit signed URL media identifier can match local file without downloading");
  check(MediaReferences.localKeys("../../outside.png").isEmpty()&&MediaReferences.localKeys("file:///private/file.png").isEmpty(),"filesystem escapes never become local media paths");
  MediaItem a=new MediaItem();a.id="hash-a";a.name="photo-"+id+".png";a.originalPath="chat_media/"+a.name;MediaItem b=new MediaItem();b.id="hash-b";b.name="item.webp";b.originalPath="custom_stickers/item.webp";
  LocalMediaIndex index=new LocalMediaIndex(Arrays.asList(a,b));check(index.resolve(id).equals("hash-a"),"UUID within filename");check(index.resolve("custom_stickers/item.webp").equals("hash-b"),"exact sticker path");check(index.resolve("item").equals("hash-b"),"extensionless metadata ID matches exact filename stem");
  MediaItem collision=new MediaItem();collision.id="hash-c";collision.name=a.name;collision.originalPath="other/"+a.name;LocalMediaIndex ambiguous=new LocalMediaIndex(Arrays.asList(a,collision));check(ambiguous.resolve(id).isEmpty(),"ambiguous media ID does not choose a file");check(ambiguous.resolve(a.originalPath).equals(a.id),"unambiguous complete path survives basename collision");
  String numeric="{\"Custom Sticker IDs\":[717330595],\"Bitmoji\":{\"Path\":\"bitmoji/a.png\"}}";refs=MediaReferences.collect(new JSONObject(numeric));check(refs.contains("717330595")&&refs.contains("bitmoji/a.png"),"numeric and nested asset fields");
  check(MediaReferences.collect(new JSONObject("{\"File\":\"custom_stickers/item.webp\"}"),true).contains("custom_stickers/item.webp"),"asset File field is a local reference");
  check(DataCategories.dataset("json/custom_stickers.json").equals("Stickers")&&DataCategories.dataset("json/unfamiliar.json").equals("Other data"),"custom and unknown datasets retained");check(DataCategories.asset("memories/date-overlay.png").equals("overlay"),"overlays identified independently from photo files");
  String text="[\"scalar\",\"emoji \\ud83d\\ude00\"]";String actual="A\ud83d\ude00B";MetadataTextPage p=MetadataTextPage.read(new StringReader(actual),0,2);check(p.text.equals("A")&&p.next==1&&!p.ended,"page never splits an emoji surrogate pair");MetadataTextPage q=MetadataTextPage.read(new StringReader(actual),p.next,2);check(q.text.equals("\ud83d\ude00")&&q.next==3,"next page preserves emoji");check(MetadataTextPage.read(new StringReader(text),0,65536).text.equals(text),"raw scalar arrays remain readable");
  File zip=File.createTempFile("synthetic-assets-",".zip"),stage=Files.createTempDirectory("synthetic-assets-stage-").toFile();try(ZipOutputStream out=new ZipOutputStream(new FileOutputStream(zip))){Map<String,String> entries=new LinkedHashMap<>();entries.put("custom_stickers/nested/asset.nomedia","raw sticker bytes");entries.put("custom_stickers/shape.svg","<svg xmlns=\"http://www.w3.org/2000/svg\"/>");entries.put("attachments/file.pdf","%PDF-synthetic");entries.put("json/custom_stickers.json","{\"Custom Stickers\":[{\"ID\":\"asset\",\"Path\":\"custom_stickers/nested/asset.nomedia\"}]}");entries.put("json/unknown_dataset.json","[\"retained\"]");for(Map.Entry<String,String> e:entries.entrySet()){out.putNextEntry(new ZipEntry(e.getKey()));out.write(e.getValue().getBytes(StandardCharsets.UTF_8));out.closeEntry();}}
  ArchiveImporter.Report report=ArchiveImporter.readFull(zip,stage,m->{},(n,total)->{});check(report.media.size()==3,"unknown sticker formats, SVG and document assets are staged");check(report.metadata.size()==2,"custom and unknown raw JSON retained alongside media");
  System.out.println(checks+" full-export reference, asset and metadata-page checks passed.");
 }
}
